#!/usr/bin/env python3
"""Lossless CSV <-> TSV converter.

CSV side follows RFC 4180: fields may be quoted, quoted fields may contain
commas, doubled quotes ("") and embedded newlines.

TSV side is one field per tab-separated column, with backslash escapes:

    \\  ->  literal backslash
    \\t ->  literal tab
    \\n ->  literal newline
    \\r ->  literal carriage return

Because every byte that could be confused with structure is escaped, the
conversion is fully lossless in both directions.
"""

from __future__ import annotations

import argparse
import csv
import io
import sys

ESCAPES = {
    "\\": "\\\\",
    "\t": "\\t",
    "\n": "\\n",
    "\r": "\\r",
}
UNESCAPES = {v: k for k, v in ESCAPES.items()}


# ----------------------------- CSV side ------------------------------------

def csv_to_rows(text: str) -> list[list[str]]:
    """Parse RFC 4180 CSV text into a list of rows of cells."""
    return list(csv.reader(io.StringIO(text, newline="")))


def rows_to_csv(rows: list[list[str]]) -> str:
    """Serialize rows to RFC 4180 CSV text."""
    buf = io.StringIO(newline="")
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerows(rows)
    return buf.getvalue()


# ----------------------------- TSV side ------------------------------------

def _escape_tsv_field(field: str) -> str:
    return "".join(ESCAPES.get(ch, ch) for ch in field)


def _unescape_tsv_field(field: str) -> str:
    out: list[str] = []
    i = 0
    while i < len(field):
        ch = field[i]
        if ch == "\\":
            if i + 1 >= len(field):
                raise ValueError(
                    f"dangling backslash at end of TSV field: {field!r}"
                )
            nxt = field[i + 1]
            if nxt not in UNESCAPES:
                raise ValueError(
                    f"invalid escape sequence \\{nxt!r} in TSV field: {field!r}"
                )
            out.append(UNESCAPES[nxt])
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def rows_to_tsv(rows: list[list[str]]) -> str:
    """Serialize rows to TSV text with backslash escapes inside fields."""
    lines = ["\t".join(_escape_tsv_field(cell) for cell in row) for row in rows]
    return "".join(line + "\n" for line in lines)


def tsv_to_rows(text: str) -> list[list[str]]:
    """Parse TSV text into rows of unescaped cells."""
    raw_lines = text.split("\n")
    if raw_lines and raw_lines[-1] == "":
        raw_lines.pop()  # drop the trailing newline artifact
    rows = []
    for raw in raw_lines:
        fields = raw.split("\t") if raw else [""]
        rows.append([_unescape_tsv_field(f) for f in fields])
    return rows


# --------------------------- conversions ------------------------------------

def csv_to_tsv(text: str) -> str:
    return rows_to_tsv(csv_to_rows(text))


def tsv_to_csv(text: str) -> str:
    return rows_to_csv(tsv_to_rows(text))


CONVERTERS = {
    ("csv", "tsv"): csv_to_tsv,
    ("tsv", "csv"): tsv_to_csv,
}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Convert between CSV (RFC 4180) and TSV, losslessly."
    )
    parser.add_argument(
        "--from",
        dest="src_format",
        required=True,
        choices=("csv", "tsv"),
        help="input format",
    )
    parser.add_argument(
        "--to",
        dest="dst_format",
        required=True,
        choices=("csv", "tsv"),
        help="output format",
    )
    parser.add_argument(
        "file",
        nargs="?",
        default="-",
        help="input file (default: stdin)",
    )
    args = parser.parse_args(argv)

    if args.src_format == args.dst_format:
        parser.error("--from and --to must differ")

    data = (
        sys.stdin.read()
        if args.file == "-"
        else open(args.file, encoding="utf-8", newline="").read()
    )
    sys.stdout.write(CONVERTERS[(args.src_format, args.dst_format)](data))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

